CustomField.formula:
if( IsClosed =false, "Current Month|Last Month|Last 90 Days2 Months Ago|Last 90 Days3 Months Ago|Last 90 DaysYTD|Last Year|Q1Q2Q3Q4",
if( 
TVM_Sales_Month_Filter_Month__c = AddMonths(TVM_Sales_Months_Static__c , 0),
"Current Month|",

if(
TVM_Sales_Month_Filter_Month__c = AddMonths(TVM_Sales_Months_Static__c , 1),
"Last Month|Last 90 Days",

if(
TVM_Sales_Month_Filter_Month__c = AddMonths(TVM_Sales_Months_Static__c , 2),
"2 Months Ago|Last 90 Days",

if(
TVM_Sales_Month_Filter_Month__c = AddMonths(TVM_Sales_Months_Static__c , 3),
"3 Months Ago|Last 90 Days",
""
))))& 

if( YEAR(TODAY()) = YEAR(TVM_Sales_Months_Static__c ) , "YTD|",
if( YEAR(TODAY())-1 = YEAR(TVM_Sales_Months_Static__c ) , "Last Year|",
"None"
)))
& "Q"&Text(Ceiling(Month(TVM_Sales_Months_Static__c )/3))
/*
Current Quarter
Last Quarter
*/
